	/* @Before */
	public void setUpPcodeStepperProviderTest()
    {
		ThemeManager themeManager = ApplicationThemeManager.getInstance();
		themeManager.setColor("color.fg.listing.pcode.label", new Color(0, 0, 255));

		traceManager = addPlugin(tool, typeof(DebuggerTraceManagerServicePlugin));
		pcodePlugin = addPlugin(tool, typeof(DebuggerPcodeStepperPlugin));
		listingPlugin = addPlugin(tool, typeof(DebuggerListingPlugin)); // For colors
		emuService = tool.getService(typeof(DebuggerEmulationService));

		pcodeProvider = waitForComponentProvider(typeof(DebuggerPcodeStepperProvider));

		createTrace();
	}

	SchemaContext buildContext() {
		return new ToySchemaBuilder()
				.useRegistersPerFrame()
				.noRegisterGroups()
				.build();
	}

	protected void populateTrace()
    {
		start = tb.addr(0x00400000);
		InstructionIterator iit;
		using (Transaction tx = tb.startTransaction())
{
			tb.createRootObject(buildContext(), "Target");
			tb.trace.getMemoryManager()
					.addRegion("Memory[echo:.text]", Lifespan.nowOn(0),
						tb.range(0x00400000, 0x0040ffff),
						TraceMemoryFlag.READ, TraceMemoryFlag.EXECUTE);

			thread = tb.getOrAddThread("Threads[1]", 0);
			tb.createObjectsFramesAndRegs(thread, Lifespan.nowOn(0), tb.host, 1);

			PcodeExecutor<byte[]> init = TraceSleighUtils.buildByteExecutor(tb.trace, 0, thread, 0);
			init.executeSleigh("pc = 0x%s;".formatted(start));

			Assembler asm = Assemblers.getAssembler(tb.trace.getFixedProgramView(0));
			iit = asm.assemble(start, "imm r0, #0x123");

		}
		imm123 = iit.next();
	}

	protected void assertEmpty() {
		assertTrue(pcodeProvider.pcodeTableModel.getModelData().isEmpty());
		assertTrue(pcodeProvider.uniqueTableModel.getModelData().isEmpty());
	}

	protected void assertDecodeStep() {
		PcodeRow row = Unique.assertOne(pcodeProvider.pcodeTableModel.getModelData());
		assertEquals(EnumPcodeRow.DECODE, row);
		assertTrue(pcodeProvider.uniqueTableModel.getModelData().isEmpty());
	}

	protected void assertPopulated() {
		assertFalse(pcodeProvider.pcodeTableModel.getModelData().isEmpty());
		// NB. I don't know what uniques, if any, are involved
	}

	/* @Test */
	public void testEmpty()
    {
		assertEmpty();
	}

	/* @Test */
	public void testCloseCurrentTraceEmpty()
    {
		populateTrace();

		TraceSchedule schedule1 = TraceSchedule.parse("0:.t%d-1".formatted(thread.getKey()));
		traceManager.openTrace(tb.trace);
		traceManager.activateThread(thread);
		waitForPass(() => assertDecodeStep());

		traceManager.activateTime(schedule1);
		waitForPass(() => assertEquals(schedule1, pcodeProvider.current.getTime()));
		waitForPass(() => assertPopulated());

		traceManager.closeTrace(tb.trace);
		waitForPass(() => assertEmpty());
	}

	/* @Test */
	public void testCustomUseropDisplay()
    {
		populateTrace();

		emuService.setEmulatorFactory(new _Anon_DefaultEmulatorFactory_1());

		// Just one p-code step to load injection (decode step)
		TraceSchedule schedule1 = TraceSchedule.parse("0:.t%d-1".formatted(thread.getKey()));
		traceManager.openTrace(tb.trace);
		traceManager.activateThread(thread);
		traceManager.activateTime(schedule1);
		waitForPass(() => assertEquals(schedule1, pcodeProvider.current.getTime()));

		waitForPass(() => assertTrue(pcodeProvider.pcodeTableModel.copyModelData()
				.stream()
				.anyMatch(r => r.getCode().contains("stepper_test_userop"))));
	}

	protected List<PcodeRow> format(string sleigh) {
		SleighLanguage language = (SleighLanguage) getToyBE64Language();
		PcodeProgram prog = SleighProgramCompiler.compileProgram(language, "test", sleigh,
			PcodeUseropLibrary.nil());
		PcodeExecutor<byte[]> executor =
			new(language, BytesPcodeArithmetic.BIG_ENDIAN, null, Reason.INSPECT);
		PcodeFrame frame = executor.begin(prog);
		PcodeRowHtmlFormatter formatter = pcodeProvider.new PcodeRowHtmlFormatter(language, frame);
		return formatter.getRows();
	}

	/* @Test */
	public void testPcodeFormatterSimple() {
		List<PcodeRow> rows = format("r0 = 1;");
		assertEquals(2, rows.size());
		assertEquals("<html></html>", rows.get(0).getLabel());
		assertEquals(typeof(FallthroughPcodeRow), rows.get(1).GetType());
	}

	/* @Test */
	public void testPcodeFormatterStartsLabel() {
		List<PcodeRow> rows = format("""
				<L0> r0 = 1;
				goto <L0>;
				""");
		assertEquals(3, rows.size());
		assertEquals("<html><font color=\"#0000ff\">&lt;0&gt;</font></html>",
			rows.get(0).getLabel());
		assertEquals("<html></html>", rows.get(1).getLabel());
		assertEquals(typeof(FallthroughPcodeRow), rows.get(2).GetType());
	}

	/* @Test */
	public void testPcodeFormatterMiddleLabel() {
		List<PcodeRow> rows = format("""
				if 1:1 goto <SKIP>;
				r0 = 1;
				<SKIP> r1 = 2;
				""");
		assertEquals(4, rows.size());
		assertEquals("<html></html>", rows.get(0).getLabel());
		assertEquals("<html></html>", rows.get(1).getLabel());
		assertEquals("<html><font color=\"#0000ff\">&lt;0&gt;</font></html>",
			rows.get(2).getLabel());
		assertEquals(typeof(FallthroughPcodeRow), rows.get(3).GetType());
	}

